def rapport_lecture(textes):
    valeurs = []
    erreurs = []
    for numero, texte in enumerate(textes, start=1):
        try:
            valeur = int(texte)
        except ValueError:
            erreurs.append({"ligne": numero, "texte": texte})
        else:
            valeurs.append(valeur)
    return {"valeurs": valeurs, "erreurs": erreurs}

